    public static PixelCanvas Draw(string name, uint rgb)
    {
        var c = new PixelCanvas(12, 12);
        if (!All.TryGetValue(name, out var rows)) return c;
        for (var y = 0; y < rows.Length; y++)
            for (var x = 0; x < rows[y].Length; x++)
                if (rows[y][x] == '#') c.Set(x, y, rgb);
        return c;
    }
